func unanswerableReason(kind string, sq symbolQuery, query string, s codeIndexScope) string {
	if s.err != nil || !s.censusKnown() { return "" }
	target := query
	if kind == "symbol" { target = sq.path }   // 163's parser separates the halves
	ext := pathExt(target)
	if ext == "" || s.representsExt(ext) { return "" }
	return fmt.Sprintf("the corpus holds NO %s file at all — %s", ext, s.extSummary())
}

func notAnswerableAnswer(reason string) string {
	return "  NOT ANSWERABLE BY THIS INDEX: " + reason + ". The query was executed and returned 0 rows, and it COULD NOT have returned a row whatever the state of the repository. This is UNKNOWN. It is NOT evidence that the target is absent, removed, renamed or inlined, and it must not contribute to a verdict of STALE …"
}

